#include <stdio.h>
#include <string.h>
#include <stdbool.h>

int main(int argc, char *argv[]) {
    if (argc < 3) {
        printf("USAGE\n");
        return 0;
    }
    char *str1 = argv[1];
    char *str2 = argv[2];
    int len1 = strlen(str1);
    int len2 = strlen(str2);
    if (len1 != len2) {
        printf("NOT_ANAGRAM\n");
        return 0;
    }
    if (len1 > 0x100) {
        printf("TOO_LONG\n");
        return 0;
    }
    int count1[256] = {0};
    int count2[256] = {0};
    for (int i = 0; i < len1; i++) {
        count1[(unsigned char)str1[i]]++;
    }
    for (int i = 0; i < len2; i++) {
        count2[(unsigned char)str2[i]]++;
    }
    bool is_anagram = true;
    for (int i = 0; i < 256; i++) {
        if (count1[i] != count2[i]) {
            is_anagram = false;
            break;
        }
    }
    if (is_anagram) {
        printf("ANAGRAM\n");
    } else {
        printf("NOT_ANAGRAM\n");
    }
    return 0;
}
